from lib import *
S = SS('f165')
R = J('f165'); r = R['rows']
g = lambda w, k: r[str(w)][k]
steps = [
    step(f"实验设置:本机 10 核,/cpu 每个请求约 10 ms 纯计算,/mixed 每个请求先等 20 ms(模拟数据库)再算同样的计算,ApacheBench 64 并发(压测工具同机运行,只看相对关系)。worker 数从 1 到 32。", t=tl(S(1)), done=lidx(S(1), '本机'), kv=KV([['/cpu', '约 10 ms 纯 CPU'], ['/mixed', '20 ms 等待 + 同样的 CPU']], ['/cpu'])),
    step(f"纯 CPU 的 /cpu:1 个 worker {g(1, 'cpu'):.0f} 请求/秒、2 个 {g(2, 'cpu'):.0f}、4 个 {g(4, 'cpu'):.0f}、8 个 {g(8, 'cpu'):.0f}、10 个 {g(10, 'cpu'):.0f},之后再加到 16 个({g(16, 'cpu'):.0f})与 32 个({g(32, 'cpu'):.0f})不再增长,p99 反而从 {g(10, 'cpu_p99')} ms 变成 {g(16, 'cpu_p99')} 与 {g(32, 'cpu_p99')} ms。计算型请求的吞吐在 worker 数达到核数(10)时到顶,再多只是在抢 CPU。", b=bars([['1 个', g(1, 'cpu'), f"{g(1, 'cpu'):.0f}"], ['4 个', g(4, 'cpu'), f"{g(4, 'cpu'):.0f}"], ['10 个', g(10, 'cpu'), f"{g(10, 'cpu'):.0f}"], ['32 个', g(32, 'cpu'), f"{g(32, 'cpu'):.0f}"]], g(10, 'cpu'), mark=[3], done=[2]), t=tl(S(1)), done=lidx(S(1), '         8 ', '        10 '), mark=lidx(S(1), '        32 '), kv=KV([['worker = 核数 (10)', f"{g(10, 'cpu'):.0f} 请求/秒,到顶"], ['32 个', f"{g(32, 'cpu'):.0f},p99 更差"]], ['worker = 核数 (10)'])),
    step(f"有等待的 /mixed:1 个 {g(1, 'mixed'):.0f} 请求/秒、4 个 {g(4, 'mixed'):.0f}、10 个 {g(10, 'mixed'):.0f}、16 个 {g(16, 'mixed'):.0f}、32 个 {g(32, 'mixed'):.0f}——超过核数之后还在涨,p99 从 10 个的 {g(10, 'mixed_p99')} ms 降到 32 个的 {g(32, 'mixed_p99')} ms。等待的时间里 CPU 空着,所以 worker 数可以超过核数;经验公式 2×核数+1(这里是 21)落在两条曲线之间。但 sync worker 要靠多开进程来换并发,代价是内存(下一步)。", b=bars([['1 个', g(1, 'mixed'), f"{g(1, 'mixed'):.0f}"], ['10 个', g(10, 'mixed'), f"{g(10, 'mixed'):.0f}"], ['32 个', g(32, 'mixed'), f"{g(32, 'mixed'):.0f}"]], g(32, 'mixed'), done=[0, 1, 2]), t=tl(S(1)), done=lidx(S(1), '        16 ', '        32 '), kv=KV([['/mixed 的 worker 数', '超过核数仍有收益'], ['代价', '每个 worker 一份内存']], ['/mixed 的 worker 数'])),
    step(f"内存:空闲时整个 gunicorn(含 master)的内存,1 个 worker {g(1, 'mem'):.0f} MB、4 个 {g(4, 'mem'):.0f} MB、10 个 {g(10, 'mem'):.0f} MB、32 个 {g(32, 'mem'):.0f} MB,大约每多一个 worker 加 {(g(32, 'mem') - g(1, 'mem')) / 31:.0f} MB(这是只加载了 Flask 的最小应用,真实应用加载了模型与扩展后每个 worker 会大得多)。worker 数受内存限制:内存不够时再多的 worker 也不能用。", t=tl(S(1)), done=lidx(S(1), '空闲内存'), kv=KV([['每个 worker', f'约 {(g(32, "mem") - g(1, "mem")) / 31:.0f} MB(最小应用)'], ['32 个 worker', f'{g(32, "mem"):.0f} MB']], ['每个 worker'])),
]
A = mkartf('f165', 165, 'Flask,gunicorn,worker数量,性能,真实验证,动画演示',
    f'在 10 核机器上实测 gunicorn worker 数量:纯 CPU 请求吞吐到 worker=核数(10 个 {g(10, "cpu"):.0f} 请求/秒)就到顶,再加到 32 个 p99 反而变差;带 20 ms 等待的请求超过核数仍在涨(10 个 {g(10, "mixed"):.0f} 到 32 个 {g(32, "mixed"):.0f} 请求/秒);每多一个 worker 约多 {(g(32, "mem") - g(1, "mem")) / 31:.0f} MB 内存。',
    'gunicorn 该开几个 worker?2×核数+1 对不对?计算型和等待型有什么区别?内存怎么算?这篇在 10 核机器上把 worker 数从 1 加到 32,把吞吐、尾延迟与内存画出来。',
    [(f'{g(10, "cpu"):.0f}', '纯 CPU 请求在 worker = 核数(10)时的请求/秒,再加 worker 不再增长'), (f'{g(10, "mixed"):.0f} → {g(32, "mixed"):.0f}', '带等待的请求从 10 个到 32 个 worker 的请求/秒'), (f'{(g(32, "mem") - g(1, "mem")) / 31:.0f} MB', '最小应用每多一个 worker 增加的内存')],
    [('实验设置与结果表', '<p>上一篇:<a href="flask-json-serialization-performance.html">JSON 序列化性能</a>;下一篇:<a href="flask-worker-timeout.html">Worker Timeout</a>。</p><p>压测工具是系统自带的 ApacheBench,与被测服务同机运行,每个数字只测一次。</p>')],
    steps, [ENV_F + '。gunicorn sync worker、ApacheBench、本机 10 核', '没有验证:gthread 与 gevent 下线程数与连接数的最优值、真实数据库连接数对 worker 数的限制(第 91 篇)、CPU 超线程的影响、容器的 CPU 限额(cgroup)下的取值、多次重复测量的方差'], 'Gunicorn Worker 数量', panels=[('t', 'term', '实验输出'), ('b', 'bars', '请求/秒'), ('kv', 'kv', '要点')])
